// Top-customers report for the finance dashboard.
// orders: [{ id, customerId, status, amountCents, currency: 'USD' | 'EUR', createdAt: ISO-8601 string }]
const EUR_TO_USD = 1.08;

function byRank(a, b) {
  if (a.spendCents !== b.spendCents) return b.spendCents - a.spendCents;
  if (a.firstOrderAt !== b.firstOrderAt) return a.firstOrderAt < b.firstOrderAt ? -1 : 1;
  return a.customerId < b.customerId ? -1 : a.customerId > b.customerId ? 1 : 0;
}

// Groups orders per customer. With sortEachStep the leaderboard is re-sorted after every
// order (the historical behaviour); otherwise the caller sorts once at the end.
// Returns { groups, totalOrder }: totalOrder is false if any value could make byRank
// something other than a strict total order (non-string ids/timestamps, non-numeric
// or NaN amounts), in which case the final order depends on the sort history.
function aggregate(orders, sortEachStep) {
  const seen = new Set();
  const byCustomer = new Map();
  const groups = [];
  let totalOrder = true;
  for (const order of orders) {
    // Upstream retries can deliver the same order twice.
    if (seen.has(order.id)) continue;
    seen.add(order.id);
    if (order.status === 'refunded') continue;

    const customerId = order.customerId;
    // NaN never matched itself under the old `===` lookup, so it always starts a new group.
    let group = customerId === customerId ? byCustomer.get(customerId) : undefined;
    if (!group) {
      group = { customerId, spendCents: 0, orderCount: 0, firstOrderAt: order.createdAt };
      groups.push(group);
      if (customerId === customerId) byCustomer.set(customerId, group);
      if (typeof customerId !== 'string') totalOrder = false;
    }
    group.orderCount++;
    if (typeof order.createdAt !== 'string') totalOrder = false;
    if (order.createdAt < group.firstOrderAt) group.firstOrderAt = order.createdAt;
    if (order.status === 'paid') {
      if (typeof order.amountCents !== 'number') totalOrder = false;
      group.spendCents += order.currency === 'EUR' ? Math.round(order.amountCents * EUR_TO_USD) : order.amountCents;
      if (Number.isNaN(group.spendCents)) totalOrder = false;
    }
    if (sortEachStep) groups.sort(byRank);
  }
  return { groups, totalOrder };
}

function summarize(orders, limit = 10) {
  const list = Array.isArray(orders) ? orders : [...orders];
  let { groups, totalOrder } = aggregate(list, false);
  // Under a strict total order, sorting once gives the same result as sorting after every
  // order. For malformed data, replay the incremental sort to reproduce its exact output.
  if (totalOrder) groups.sort(byRank);
  else groups = aggregate(list, true).groups;
  return groups
    .filter((g) => g.spendCents > 0)
    .slice(0, limit)
    .map((g, i) => ({ rank: i + 1, ...g }));
}

module.exports = { summarize };
EOF

